local CymbalMaker = {}
local PRODUCTS = {
    brass_cymbal = { name = "Medeninasti činela", brassCost = 2, time = 2, cost = 30, soundQuality = 8, prestige = 1, description = "Medeninasti činela za vojaške godbe." },
    bronze_cymbal = { name = "Bronasti činela", bronzeCost = 2, time = 3, cost = 75, soundQuality = 11, prestige = 2, description = "Bronasti činela z bogatim zvokom." },
    finger_cymbal = { name = "Prstni činel", silverCost = 1, brassCost = 1, time = 4, cost = 160, soundQuality = 14, prestige = 4, happiness = 1, description = "Prstni činel za plesalce." },
    silver_cymbal = { name = "Srebrni činela", silverCost = 2, time = 5, cost = 340, soundQuality = 18, prestige = 8, happiness = 2, description = "Srebrni činela za slovesne godbe." },
    gold_cymbal = { name = "Zlati činela", goldCost = 1, silverCost = 1, time = 7, cost = 720, soundQuality = 24, prestige = 15, happiness = 3, description = "Zlati činela za kraljevske godbe." },
    royal_cymbal_pair = { name = "Kraljevski par činel", goldCost = 2, silverCost = 2, bronzeCost = 2, time = 11, cost = 1600, soundQuality = 35, prestige = 38, happiness = 7, description = "Veliki kraljevski par činel z zlatim in srebrnim zvokom." },
}
local BUILDINGS = {
    workshop = { name = "Činelarska delavnica", cost = { gold = 250, wood = 110 }, upkeep = 6, qualityBonus = 5 },
    forge = { name = "Činelarska kovačija", cost = { gold = 800, wood = 220, stone = 200, brass = 6 }, upkeep = 20, qualityBonus = 18 },
    hammering_room = { name = "Kladivnica", cost = { gold = 1700, wood = 280, stone = 350, silver = 25, bronze = 8 }, upkeep = 40, qualityBonus = 30 },
    royal_cymbal_atelier = { name = "Kraljevski atelje činel", cost = { gold = 6500, wood = 500, stone = 700, gold = 50, silver = 30 }, upkeep = 120, qualityBonus = 55, prestigeBonus = 30 },
}
CymbalMaker.brassStock = 10; CymbalMaker.bronzeStock = 10; CymbalMaker.silverStock = 8; CymbalMaker.goldStock = 6
CymbalMaker.productStock = {}; CymbalMaker.buildings = {}; CymbalMaker.maker = nil; CymbalMaker.activeMaking = {}; CymbalMaker.totalProducts = 0; CymbalMaker.dayTimer = 0
function CymbalMaker.init() CymbalMaker.brassStock=10; CymbalMaker.bronzeStock=10; CymbalMaker.silverStock=8; CymbalMaker.goldStock=6; CymbalMaker.productStock={}; CymbalMaker.buildings={}; CymbalMaker.maker=nil; CymbalMaker.activeMaking={}; CymbalMaker.totalProducts=0; CymbalMaker.dayTimer=0; print("[CymbalMaker] Royal Cymbal Maker System initialized (6 products, 4 buildings)") end
function CymbalMaker.hireMaker(n,s) s=s or math.random(50,90); local c=460+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CymbalMaker.maker={name=n or ("Činelar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Činelar najet: %s (spretnost: %d)",CymbalMaker.maker.name,s),"success") end; return true end
function CymbalMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CymbalMaker.build(id) local ok,e=CymbalMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CymbalMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CymbalMaker.getQualityBonus() local b=0; for _,bd in ipairs(CymbalMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CymbalMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.brassCost and CymbalMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.bronzeCost and CymbalMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.silverCost and CymbalMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CymbalMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if #CymbalMaker.buildings==0 then return false,"Potrebna delavnica" end; if not CymbalMaker.maker then return false,"Potreben činelar" end; return true end
function CymbalMaker.make(pt,qty) qty=qty or 1; local ok,e=CymbalMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.brassCost then CymbalMaker.brassStock=CymbalMaker.brassStock-d.brassCost*qty end; if d.bronzeCost then CymbalMaker.bronzeStock=CymbalMaker.bronzeStock-d.bronzeCost*qty end; if d.silverCost then CymbalMaker.silverStock=CymbalMaker.silverStock-d.silverCost*qty end; if d.goldCost then CymbalMaker.goldStock=CymbalMaker.goldStock-d.goldCost*qty end; local t=d.time; if CymbalMaker.maker then t=math.max(1,t-math.floor(CymbalMaker.maker.skill/12)) end; table.insert(CymbalMaker.activeMaking,{id="cymbal_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,soundQuality=d.soundQuality or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CymbalMaker.completeMaking(m) local q=1.0+(CymbalMaker.getQualityBonus()/100); if CymbalMaker.maker then q=q+(CymbalMaker.maker.skill/180) end; q=math.min(2.0,q); CymbalMaker.productStock[m.productType]=(CymbalMaker.productStock[m.productType] or 0)+m.quantity; CymbalMaker.totalProducts=CymbalMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CymbalMaker.maker then CymbalMaker.maker.itemsMade=CymbalMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then CymbalMaker.maker.skill=math.min(100,CymbalMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Činela izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"cymbal.completed",{productName=m.productName,soundQuality=m.soundQuality}) end end
function CymbalMaker.update(dt) if not _G.state then return end; CymbalMaker.dayTimer=CymbalMaker.dayTimer+dt; if CymbalMaker.dayTimer>=30 then CymbalMaker.dayTimer=0; for i=#CymbalMaker.activeMaking,1,-1 do local m=CymbalMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CymbalMaker.completeMaking(m); table.remove(CymbalMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CymbalMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CymbalMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CymbalMaker.getStats() return {brassStock=CymbalMaker.brassStock,bronzeStock=CymbalMaker.bronzeStock,silverStock=CymbalMaker.silverStock,goldStock=CymbalMaker.goldStock,productStock=CymbalMaker.productStock,numBuildings=#CymbalMaker.buildings,hasMaker=CymbalMaker.maker~=nil,makerName=CymbalMaker.maker and CymbalMaker.maker.name or "—",makerSkill=CymbalMaker.maker and CymbalMaker.maker.skill or 0,activeMaking=#CymbalMaker.activeMaking,totalProducts=CymbalMaker.totalProducts} end
return CymbalMaker
